function maxProfitWithFee(prices, fee) {
  if (prices.length === 0) return 0
  let cash = 0
  let hold = -prices[0]
  for (let i = 1; i < prices.length; i++) {
    const p = prices[i]
    const nc = Math.max(cash, hold + p - fee)
    const nh = Math.max(hold, cash - p)
    cash = nc
    hold = nh
  }
  return cash
}

