function tsp(dist) {
  const n = dist.length
  if (n <= 1) return 0
  const full = (1 << n) - 1
  const dp = Array.from({ length: 1 << n }, () => new Array(n).fill(Infinity))
  dp[1][0] = 0
  for (let mask = 1; mask <= full; mask++) {
    for (let last = 0; last < n; last++) {
      const cur = dp[mask][last]
      if (cur === Infinity || !(mask & (1 << last))) continue
      for (let nx = 0; nx < n; nx++) {
        if (mask & (1 << nx)) continue
        const nm = mask | (1 << nx)
        const cost = cur + dist[last][nx]
        if (cost < dp[nm][nx]) dp[nm][nx] = cost
      }
    }
  }
  let best = Infinity
  for (let last = 1; last < n; last++) best = Math.min(best, dp[full][last] + dist[last][0])
  return best
}

